INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61917783', 61917783, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK KOTA - JAKBAR', 'Tenaga Komunikasi Informasi Publik Editor Video', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 115063650, 'November 2025', 'APBD', 1, 1, '1 Orang x 13 Bulan', 'a. Melaksanakan perancangan kebutuhan materi video/foto yang akan dipublikasikan di media resmi Pemerintah Kota Administrasi Jakarta Barat. b. Melaksanakan koordinasi dengan Kameramen/ Fotografer terkait kebutuhan video/foto. c. Melaksanakan penyuntingan video/audio/foto kebutuhan Pemerintah Kota Administrasi Jakarta Barat. d. Menginformasikan video yang telah dibuat untuk kebutuhan publikasi di youtube dan media sosial. e. Melaksanakan dukungan monitoring penyimpanan bulanan file video dan foto yang telah terkumpul dari Kameramen pada tempat penyimpanan yang telah ditentukan. f. Melaksanakan dukungan pengambilan dokumentasi foto/video di lingkungan Pemerintah Kota Adm Jakarta Barat. g. Menyusun laporan dan dokumentasi pekerjaan. h. Melaksanakan tugas lain yang diperintahkan pimpinan.', 'a. Pendidikan minimal D3, diutamakan jurusan Multimedia/Desain Komunikasi Visual/Sistem Informasi/Manajemen Informatika; b. Memiliki pengalaman kerja sebagai editor audio video minimal 1 tahun yang dibuktikan dengan surat keterangan pengalaman kerja; c. Memiliki kemampuan editing video dan audio untuk kebutuhan berita dan konten media sosial dan lainnya; d. Memiliki pengetahuan yang baik terkait editing tools (Adobe Premiere Pro, Cap Cut, After Effect, dsb); e. Memiliki kreatifitas yang tinggi serta memahami tren sosial dan digital saat ini; f. Memiliki taste yang menarik dalam pemilihan materi video dan backsound; g. Memiliki sertifikat keahlian/kompetensi sebagai editor audio video yang dikeluarkan maksimal 2 tahun terakhir; h. Memiliki kemampuan fotografi/videografi dan desain grafis menjadi nilai tambah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 30081);
