INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61920149', 61920149, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK KOTA - JAKBAR', 'Tenaga Komunikasi Informasi Publik Editor Berita', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 115063650, 'November 2025', 'APBD', 1, 1, '1 Orang x 13 Bulan', 'a. Melaksanakan pengeditan naskah berita serta caption media sosial untuk ditayangkan sesuai kaidah jurnalistik. b. Melaksanakan dukungan penyusunan berita/siaran pers tentang kegiatan, kebijakan dan program Pemerintah Kota Administrasi, serta kebutuhan konten publikasi. c. Berkoordinasi dengan reporter dan tim dokumentasi terkait materi peliputan lapangan dan kebutuhan pengambilan foto/video publikasi. d. Memilah dan memilih foto dan video yang akan dipublikasikan. e. Bertanggung jawab terhadap kualitas dan faktual berita. f. Melaksanakan dukungan pengambilan foto/video untuk kebutuhan dokumentasi dan publikasi. g. Menyusun laporan dan dokumentasi pekerjaan. h. Melaksanakan tugas lain yang diperintahkan pimpinan.', 'a. Pendidikan minimal D4/S1, diutamakan jurusan Ilmu Komunikasi/Bahasa Indonesia; b. Memiliki pengalaman kerja di bidang jurnalistik minimal 2 tahun yang dibuktikan dengan surat keterangan pengalaman kerja; c. Memiliki kemampuan menyusun dan mengedit berita, membuat caption media sosial yang menarik, serta menyusun press release sesuai dengan kaidah jurnalistik; d. Memiliki kemampuan menyelaraskan bahasa sesuai dengan kaidah Ejaan Yang Disempurnakan (EYD) pada setiap materi publikasi; e. Memiliki sertifikat keahlian/kompetensi di bidang jurnalistik yang dikeluarkan maksimal 2 tahun terakhir; f. Memiliki kemampuan fotografi/videografi menjadi nilai tambah; g. Diutamakan memiliki pemahaman yang baik terhadap wilayah Jakarta Barat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 30146);
