INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61866473', 61866473, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tenaga Sub Profesional - Tim Pembangunan, Pengembangan dan Pengelolaan Sistem Informasi Geografis Jakarta Satu - (Senior Assistant Professional Staff - Spatial Database)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 180180000, 'December 2025', 'APBD', 1, 1, '2 orang x 12 bulan', 'a. Bertanggung jawab terhadap seluruh pelaksanaan pekerjaan sesuai dengan spesifikasi teknis yang ditetapkan; b. Membantu merencanakan, mengonsep, dan mengolah data spasial dan tabular yang ada di Jakarta Satu; c. Mengimplementasikan struktur data KUGI dan standarisasi lain yang ditetapkan pada data Jakarta Satu; d. Membantu mendokumentasikan dan mempublikasikan hasil statistik data Jakarta Satu dalam bentuk dashboard dan infografis; e. Membantu melakukan geocoding dalam transformasi data atribut menjadi koordinat geografis untuk keperluan analisis spasial; f. Membantu melakukan monitoring data untuk mendukung pengelolaan dalam penyimpanan data geospasial;g. g. Membantu melakukan analisa terhadap layanan permintaan data yang ada dalam portal Jakarta Satu; h. Membantu pelaksanaan SDI di tingkat provinsi; i. Membantu analisis data dalam bentuk materi presentasi atau visual dengan cara yang efektif j. Membantu Memberikan dukungan sharing knowledge, mentoring, dan pendampingan teknis penggunaan perangkat lunak GIS serta teknologi pendukungnya; k. Memastikan seluruh pekerjaan dikerjakan secara efektif dan efisien; l. Melakukan koordinasi dengan tim lain Jakarta Satu untuk pengembangan geospasial Jakarta Satu; m. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas setiap bulanan dan tahunan; n. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan.', 'a. Memiliki Pendidikan Minimal S1 Teknik Geodesi / Teknik Geodesi dan Geomatika; b. Memiliki pengalaman 1 tahun di bidang Geographic Information System (GIS); c. Mempunyai KBLI 63111;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 30246);
