INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61849497', 61849497, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK KOTA - JAKTIM', 'PJLP Designer Grafis Intermediate Kominfotik Jakarta Timur', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 117002925, 'December 2025', 'APBD', 1, 1, '1 orang x 13 bulan', '"Menerima, menyunting dan menata letak hasil foto liputan untuk diolah sebagai publikasi pemberitaan di media sosial; Menyusun rencana publikasi (editorial plan) bersama dengan tim; Menyusun dan melaksanakan pembuatan konten kreatif, mulai dari pembuatan konsep, pengambilan, penyuntingan sampai berupa konten jadi; Memeriksa keselarasan bahasa yang digunakan dalam takarir (caption) media sosial; Menyusun dan melaksanakan pembuatan desain grafis dan motion grafis, mulai dari pembuatan konsep, pengambilan dan/atau ilustrasi, penyuntingan dan finalisasi sampai berupa konten jadi; Melaksanakan tugas lainnya sesuai perintah/permintaan baik tertulis maupun lisan dari staf dan/atau Kepala Seksi Komunikasi dan Informasi Publik; Bertanggung jawab untuk menjaga perangkat keras yang digunakan dalam menunjang proses pembuatan konten kreatif, desain grafis dan motion grafis; Bertanggung jawab terhadap keseluruhan proses pembuatan desain grafis dan motion grafis yang ditugaskan; Bertanggung jawab terhadap keseluruhan proses pembuatan konten kreatif yang ditugaskan; Membuat laporan kegiatan kerja."', '"Pendidikan minimal D3 Memiliki keahlian tentang desain grafis, motion dan komunikasi visual; Memiliki keahlian mengoperasikan software desain grafis. motion, editing audio video; dan komunikasi visual; Memiliki kemampuan fotografi dan videografi menjadi nilai tambah; Memiliki kreativitas tinggi serta memahami tren sosial terkini; Memiliki pengalaman kerja di bidang Pemerintahan; Memiliki sertifikat sesuai dibidangnya"', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 30323);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62945001', 62945001, 'analyze_legacy', 'Kota Bandung', 'kabkota', 'Dinas Komunikasi dan Informatika', 'Pembulatan', 'Jasa Lainnya', 'Dikecualikan', 'Jawa Barat, Bandung (Kota)', 8600, 'January 2026', 'APBD', 1, 1, '1', 'Pmebulatan', 'Pembulatan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 30324);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62044229', 62044229, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'BADAN PELAYANAN PENGADAAN BARANG/JASA', 'Penyediaan Tenaga Ahli - Paralegal', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 140821200, 'December 2025', 'APBD', 1, 1, '2 orang', 'Ruang lingkup pekerjaan Penyediaan Tenaga Ahli – Paralegal (PJLP) meliputi: a. membantu Kasubbid dan/atau Pelaksana Subbid Pendampingan Pengadaan dalam melakukan pendampingan kepada Kelompok Kerja Pemilihan (Pokja) dalam menghadapi permasalahan hukum pengadaan barang/jasa di tingkat mediasi, penyelidikan, penyidikan, dan pengadilan; b. membantu dalam pemberian pelayanan pendampingan penyelesaian sengketa kontrak pengadaan barang/jasa kepada PPK (Pejabat Penandatangan Kontrak) melalui mediasi; c. membantu mengelola arsip / dokumen hukum (JDIH) pada laman BPPBJ; d. membantu pengadministrasian artikel hukum terkait permasalahan hukum dalam pengadaan barang/jasa; e. membantu membuat bahan sosialisasi melalui berbagai media, di antaranya infografis, paparan, dan/atau video; f. mendukung hal yang berkenaan dengan pelayanan hukum yaitu membantu pelaksanaan tugas dan fungsi Subbidang Pendampingan Pengadaan dan melaksanakan tugas lainnya dari atasan.', 'pria/wanita, pendidikan minimal S1 Hukum, IPK 3,00 dari skala 4,00, usia maksimal 40 tahun per 1 Januari 2026, diutamakan memiliki pengalaman di Bidang Hukum 1 (satu) tahun, diutamakan telah mengikuti PKPA', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 30325);
