INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61860875', 61860875, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS TENAGA KERJA, TRANSMIGRASI, DAN ENERGI KOTA ADMINISTRASI JAKARTA UTARA', 'Penyediaan Jasa PJLP Pendamping Kewirausahaan di Wilayah Jakarta Utara', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Utara (Kota)', 861038100, 'November 2025', 'APBD', 1, 1, '12 Orang', 'Uraian Pekerjaan Penyediaan Jasa PJLP Pendamping Kewirausahaan di Wilayah Jakarta Utara : Pendaftaran - Melakukan koordinasi dengan instansi terkait dalam rangka pendaftaran Program Pengembangan Kewirausahaan Terpadu (PKT); - Melakukan Sosialisasi dan Rekrutmen Program PKT (Jakpreneur) dari masyarakat, Kelurahan maupun komunitas; - Melakukan Sosialisasi Penggunaan Platform jakpreneur.jakarta.go.id kepada pelaku usaha yang bergabung untuk dapat mengakses sistem secara mandiri - Melakukan set Pendamping untuk peserta PKT yang baru bergabung dengan mengarahkan ke Kasatpel sesuai wilayah domisi usaha/rumahnya - Melakukan klasifikasi dan merekapitulasi peserta PKT tingkat Kecamatan yang meliputi Wirausaha Baru, Wirausaha Naik Kelas dan/atau Pencari Kerja serta melaporkan secara berjenjang. Pelatihan - Melakukan koordinasi dengan instansi terkait dalam rangka pelaksanaan Pelatihan Program Pengembangan Kewirausahaan Terpadu (PKT); - Menyampaikan jadwal pelatihan yang akan diselenggarakan ke Pendamping Tingkat Kota untuk diupload pada sistem jakpreneur.jakarta.go.id - Melakukan undangan atau penyampaian informasi pelatihan baik dalam bentuk flyer maupun infografis lainnya dan memastikan peserta melakukan pendaftaran pelatihan melalui sistem jakpreneur.jakarta.go.id - Menghadirkan peserta pelatihan pada kegiatan pembinaan kewirausahaan tingkat Kecamatan; - Merekapitulasi data peserta yang mengikuti pelatihan dengan mencocokkan absensi manual dengan mengupdate pada sistem jakpreneur.jakarta.go.id ; - Melakukan updating tahapan pelatihan pada database terhadap setiap peserta pembinaan kewirausahaan tingkat Kecamatan. Pendampingan - Melakukan pendampingan bagi para peserta pelatihan dari tahap pendaftaran (P1) sampai tahap permodalan (P7); - Memastikan peserta mengajukan permohonan Pendampingan melalui sistem jakpreneur.jakarta.go.id dan menindaklanjuti permohonan pendampingan melalui sistem jakpreneur.jakarta.go.id sampai peserta memberikan penilaian terhadap hasil pendampingan melalui sistem jakpreneur.jakarta.go.id - Memastikan peserta jakpreneur untuk mengupdate/reaktivasi profil usaha secara mandiri sebelum difasilitasi Pelatihan sampai dengan permodalan - Melakukan pendampingan mencari ide usaha dan memulai usaha bagi para peserta PKT yang belum memiliki usaha; - Melakukan pendampingan terhadap peningkatan aset, omset dan tenaga kerja para pelaku usaha. Perizinan - Membantu para pelaku usaha untuk mendapatkan perizinan usaha maupun perizinan produk; - Mendata para pelaku usaha yang sudah mendapatkan perizinan. Pemasaran - Melakukan koordinasi dengan instansi terkait dalam rangka pelaksanaan Pemasaran pada Program PKT; - Menyampaikan jadwal pemasaran/ bazar yang akan diselenggarakan kepada Pendamping Tingkat Kota untuk diupload disistem jakpreneur.jakarta.go.id - Menyampaikan informasi pemasaran baik dalam bentuk flyer maupun infografis lainnya dan memastikan peserta mendaftar pemasaran/bazzar melalui sistem jakpreneur.jakarta.go.id - Melakukan kurasi peserta bazar melalui sistem jakpreneur.jakarta.go.id - Mendampingi dan memonitor peserta bazar dalam melaporkan omsetnya per hari selama kegiatan berlangsung - Melakukan pendampingan dalam pembuatan QRIS sebagai sarana pembayaran pada bazar online maupun offline - Merekap Jakpreneur yang desain kemasan maupun foto produknya belum layak untuk diikutkan pada pelatihan dan pendampingan lanjutan - Memverifikasi katalog produk binaan pada sistem jakpreneur (Judul, Foto produk, deskripsi Produk, Harga, Nomor Kontak usaha dan link pemasaran yang bisa diakses (Instagram, marketplace, dll)) - Melakukan pendataan dan klasifikasi produk para pelaku usaha di setiap Kecamatan; - Membantu memasarkan produk para pelaku usaha baik melalui kegiatan pemasaran offline maupun online; - Melaporkan kegiatan pemasaran yang telah dilaksanakan melalui sistem jakpreneur.jakarta.go.id (Jumlah peserta yang terlibat, Omset , dan jumlah pengunjung). Pelaporan Keuangan - Melakukan pengarahan dalam pembuatan NPWP bagi pelaku usaha - Menghimbau peserta yang telah memiliki kewajiban untuk melaporkan SPT Tahunan pada triwulan I - Melakukan pendampingan penyusunan laporan keuangan bagi peserta pelatihan; - Memverifikasi dan merekapitulasi data peserta pelatihan yang telah mendapatkan fasilitasi pelaporan keuangan. Permodalan: - Membantu para pelaku usaha untuk mengajukan atau medapatkan fasilitas permodalan; - Mendata para pelaku usaha yang telah mendapatkan fasilitas permodalan; - Melakukan updating tahapan permodalan pada database terhadap setiap peserta pelatihan.', 'Minimal Sarjana bidang yang relevan, mempunyai sertifikat pendamping wirausaha', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 30703);
