INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63004151', 63004151, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Alat Tulis Kantor - Keberatan', 'Barang', 'Pengadaan Langsung', 'Jawa Timur, Sidoarjo (Kab.)', 132090, 'February 2026', 'APBD', 1, 1, '5 Pak', 'Uraian pekerjaan Pengadaan Isi Staples Kecil ini meliputi kegiatan pengadaan, penyediaan, dan penyerahan isi staples kecil yang digunakan untuk menunjang kelancaran kegiatan administrasi perkantoran, khususnya dalam pengarsipan dan pengelolaan dokumen pada perangkat daerah. Pekerjaan ini mencakup penyediaan isi staples kecil yang memenuhi spesifikasi teknis, memiliki daya rekat dan kekuatan yang baik, tidak mudah berkarat, serta kompatibel dengan stapler standar ukuran kecil yang digunakan di lingkungan perkantoran. Isi staples yang disediakan harus dalam kondisi baru, tidak rusak, dan dikemas rapi dalam kemasan pabrik', '1. Nama Barang Isi Staples Kecil 2. Jenis Barang Alat Tulis Kantor (ATK) 3. Bahan Kawat baja berkualitas Lapisan anti karat (galvanis atau setara) 4. Ukuran Staples Ukuran: No. 10 (atau setara untuk stapler kecil standar) Panjang kaki staples: ± 5 mm Lebar staples: ± 9 mm 5. Kapasitas Penjepitan Mampu menjepit ± 10–15 lembar kertas HVS 70–80 gsm 6. Warna Perak / metalik 7. Karakteristik Teknis Kuat dan tidak mudah patah Tidak mudah berkarat Presisi, tidak mudah macet pada stapler Hasil jepitan rapi dan kuat 8. Kemasan Dikemas dalam strip/pita staples Jumlah per kotak: ± 1.000 isi (menyesuaikan standar pabrik) Kemasan pabrik masih tersegel dan berlabel jelas 9. Kondisi Barang Baru (bukan bekas atau rekondisi) Tidak bengkok, tidak berkarat, dan tidak rusak 10. Standar Mutu Memenuhi standar mutu ATK yang berlaku Setara dengan produk yang umum digunakan di perkantoran 11. Jumlah Sesuai kebutuhan dan tercantum dalam kontrak atau surat pesanan 12. Tempat dan Waktu Pengiriman Lokasi pengiriman: Sesuai penetapan PPK/Pejabat Pengadaan Waktu pengiriman: Sesuai ketentuan dalam kontrak/SP 13. Pemeriksaan dan Serah Terima Diperiksa oleh PPK Serah terima dituangkan dalam Berita Acara Serah Terima (BAST)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 33892);
