INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61841600', 61841600, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PANTI SOSIAL BINA LARAS HARAPAN SENTOSA 2', 'Pengadaan Petugas Kebersihan Dalam Gedung Panti Sosial Bina Laras Harapan Sentosa 2 Tahun 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 280631572, 'November 2025', 'APBD', 1, 1, '4 Orang x 13 Bulan', 'Ruang lingkup pekerjaan meliputi: 1. Menjaga kebersihan, kerapihan, dan keindahan di lingkungan kantor seperti gedung kantor, halaman, taman, ruang aula, mushola, kamar mandi/toilet kantor; 2. Menyiapkan tempat rapat atau acara seremonial; 3. Membersihkan gudang; 4. Menata letak dan susunan sarpras kerja; 5. Mengepel lantai, membersihkan kaca, dan dinding; 6. Membersihkan meja dan kursi; 7. Mendampingi petugas pengangkut sampah; 8. Bertanggung jawab terhadap penggunaan peralatan kerja dan menjaga sebaik mungkin; 9. Melakukan pendampingan bagi WBS terhadap kebersihan dan kerapian asrama dan lingkungan sekitar dalam mengikuti kegiatan sehari-hari dalam mengikuti kegiatan sehari di panti seperti activity daily living, ibadah, makan, mandi, piket, apel, kerja bakti, belajar dan sebagainya; 10.Mematuhi jadwal dan bertanggung jawab terhadap kebersihan di lokasi kerja yang ditentukan; 11.Memberi pelayanan kepada tamu dan masyarakat yang datang ke kantor; 12.Melaksanakan tugas kedinasan lainnya baik lisan maupun tulisan yang masih menjadi bagian pekerjaannya; 13.Mencatat dan melaporkan kinerja harian dan menyerahkan ke Ka Sub Bagian Tata Usaha maksimal tanggal 5 (lima) setiap bulannya.', '- Warga Negara Indonesia; - Bertakwa kepada Tuhan Yang Maha Esa dan taat kepada Pancasila, Undang-Undang Dasar Tahun 1945 serta Negara Kesatuan Republik Indonesia; - Berjenis kelamin perempuan atau laki-laki dengan usia paling rendah 18 tahun 0 bulan 0 hari dan paling tinggi 56 tahun 0 bulan 0 hari pada tanggal 1 Januari 2025 (sesuai Keputusan Gubernur Nomor 1095 Tahun 2022); - Pendidikan minimal lulusan SLTA/sederajat atau SLTP/sederajat yang sedang mengikuti Paket C, dibuktikan dengan surat keterangan; - Sanggup bekerja penuh waktu; - Bersedia ditugaskan di lingkungan kerja Panti Sosial Bina Laras Harapan Sentosa 2 dan diluar jam kerja;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 33905);
