INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61866444', 61866444, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tenaga Sub Profesional - Tim Pembangunan, Pengembangan dan Pengelolaan Sistem Informasi Geografis Jakarta Satu - (Senior Assistant Professional Staff - GIS Developer and Education Tim)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 180180000, 'December 2025', 'APBD', 1, 1, '2 orang x 12 bulan', 'a. Bertanggung jawab terhadap seluruh pelaksanaan pekerjaan sesuai dengan spesifikasi teknis yang ditetapkan; b. Membantu proses integrasi, masteri pengolahan, dan pengelolaan manajemen data, analisa data dan metadata data, processing data dan transformasi data dan informasi spasial bersama Aspro agar data dapat masuk ke dalam portal Jakarta Satu; c. Membantu quality control (QC) terhadap data dan informasi spasial yang dikerjakan Aspro untuk menjamin akurasi, kelengkapan, konsistensi, dan keterbaruan sesuai dengan standarisasi yang telah ditetapkan; d. Membantu pelaksanaan workshop, sosialisasi, atau pelatihan terkait akuisisi, integrasi, dan pengolahan data geospasial bagi seluruh Perangkat Daerah/Unit Perangkat Daerah di lingkungan Pemerintah Provinsi DKI Jakarta; e. Membantu melakukan monitoring seluruh data di Jakarta Satu; f. Mendukung pelaksanaan SDI di tingkat provinsi; g. Membantu implementasi peningkatan integrasi simpul jaringan Jakarta Satu agar data dan layanan terdistribusi secara efisien antar unit; h. Memberikan dukungan sharing knowledge, mentoring, dan pendampingan teknis penggunaan perangkat lunak GIS serta teknologi pendukungnya. i. Membantu perumusan konsep dan pelaksanaan kegiatan terkait Jakarta Satu Festival; j. Memastikan seluruh pekerjaan dikerjakan secara efektif dan efisien; k. Melakukan koordinasi dengan tim lain Jakarta Satu untuk pengembangan geospasial Jakarta Satu; l. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas setiap bulanan dan tahunan; m. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan', 'a. Memiliki Pendidikan Minimal S1 Teknik Geodesi/Teknik Informatika; b. Memiliki pengalaman 1 tahun di bidang Geographic Information System (GIS); c. Mempunyai KBLI 63111 / 63112 / 71102', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 34530);
