INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62150945', 62150945, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA PUSAT', 'Penyusunan Dokumen Teknis Gedung Pemda - SAPS 4 (Struktur) 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82582500, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Lingkup kegiatan yang dilakukan oleh penyedia jasa Senior Assistant Professional Staff (SAPS) 4 - Struktur, meliputi: Membantu penilaian teknis terhadap gambar, spesifikasi dan rencana anggaran biaya pada bidang struktur tahap perencanaan pembangunan yang diajukan oleh Perangkat Daerah pengguna anggaran; Membantu konsultasi dan evaluasi tahap perencanaan pembangunan baru bidang struktur; Membantu dalam menyusun bahan persetujuan teknis pada bidang struktur tahap perencanaan pembangunan, perawatan dan pemeliharaan; Membantu penyusunan Gambar Kerja Struktur bidang gedung pemerintah daerah;. Membantu penyusunan Pengembangan Rencana Struktur, yang dibutuhkan untuk kegiatan perencanaan pembangunan ; Membantu pelaksanaan Review Desain meliputi gambar - gambar detail struktur yang sesuai dengan gambar yang disetujui untuk kegiatan perencanaan pembangunan,; Membantu menyusun Rencana Anggaran Biaya (RAB); Membantu menyusun Rencana Kerja dan Syarat-syarat (RKS); Membantu menyusun Standar Harga Satuan Tertinggi (SHST) terhadap rencana pembangunan gedung baru; Melaksanakan Survei lapangan; dan Membantu dalam pemutakhiran data dan peta "', '"Senior Assistant Profesional Staff bidang Struktur dengan ketentuan sebagai berikut : a. Pendidikan Minimal S1/D4/Setara Jurusan Teknik Sipil dari Universitas Negeri/ Swasta dengan status lain yang telah mengikuti ujian negara atau lulusan luar negeri bagi penyedia jasa Senior Assistant Professional Staff; b. Memiliki kompetensi sesuai bidang yang dipersyaratkan yang dibuktikan dengan ijazah dan transkrip nilai pendidikan terakhir Jurusan Teknik Sipil sertifikat keahlian/teknis seperti aplikasi AutoCAD, SAP 2000/Etabs, Microsoft Office dan/atau sertifikat pelatihan/kursus; dan c. Pengalaman Kerja minimal 1 tahun di bidang perencanaan, pembangunan, perawatan bangunan gedung dan/atau pekerjaan sejenis."', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 37274);
