INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62906610', 62906610, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Hadiah - Penghargaan Wajib Pajak', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 119872000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Hadiah - Penghargaan Wajib Pajak berupa Televisi, Blender dan Kompor Gas Uraian pekerjaan ini meliputi kegiatan pengadaan dan penyediaan hadiah penghargaan yang diberikan kepada wajib pajak sebagai bentuk apresiasi atas kepatuhan, ketertiban, dan kontribusi dalam memenuhi kewajiban perpajakan daerah. Pemberian hadiah ini bertujuan untuk meningkatkan motivasi, kesadaran, dan partisipasi wajib pajak dalam mendukung optimalisasi penerimaan daerah. Hadiah yang disediakan harus memiliki kualitas baik, layak digunakan, serta sesuai dengan ketentuan peraturan perundang-undangan yang berlaku. Ruang Lingkup Pekerjaan meliputi: Pengadaan Hadiah Penyediaan hadiah sesuai jenis, jumlah, dan spesifikasi teknis yang ditetapkan. Hadiah dalam kondisi baru, bukan barang bekas atau rekondisi. Kesesuaian dan Kualitas Hadiah memiliki nilai guna dan kualitas yang baik. Jenis hadiah disesuaikan dengan ketentuan dan tujuan pemberian penghargaan. Pengemasan dan Pengiriman Pengemasan hadiah dilakukan secara rapi dan aman. Pengiriman hadiah ke lokasi yang ditentukan oleh PPK. Pemeriksaan Barang Pemeriksaan fisik dan kelengkapan hadiah. Pemeriksaan kesesuaian dengan spesifikasi yang disepakati. Penggantian Hadiah Penggantian hadiah apabila terdapat kerusakan, cacat produksi, atau ketidaksesuaian spesifikasi. Serah Terima Pekerjaan Serah terima hadiah dituangkan dalam Berita Acara Serah Terima (BAST). Dengan terlaksananya pekerjaan ini, diharapkan pemberian hadiah penghargaan kepada wajib pajak dapat berjalan tertib, transparan, dan memberikan dampak positif terhadap peningkatan kepatuhan pajak.', 'Belanja Hadiah untuk Penghargaan kepada Wajib Pajak 1. Nama Pekerjaan Belanja Hadiah untuk Penghargaan kepada Wajib Pajak 2. Jenis Pekerjaan Pengadaan Barang (Hadiah/Apresiasi) 3. Maksud dan Tujuan Menyediakan hadiah sebagai bentuk penghargaan dan apresiasi kepada wajib pajak yang patuh dan berprestasi dalam memenuhi kewajiban perpajakan daerah, guna meningkatkan motivasi dan kepatuhan pajak. 4. Ruang Lingkup Pekerjaan Ruang lingkup pekerjaan meliputi: Pengadaan hadiah sesuai jenis dan jumlah yang ditetapkan. Penyediaan hadiah dengan kualitas dan nilai guna yang baik. Pengemasan dan pengiriman hadiah ke lokasi yang ditentukan. Pemeriksaan dan serah terima barang. 5. Spesifikasi Teknis Hadiah 5.1 Jenis Hadiah Hadiah berupa barang elektronik dan/atau non-elektronik Jenis hadiah disesuaikan dengan ketentuan yang berlaku dan kebutuhan kegiatan 5.2 Kriteria Umum Hadiah Memiliki nilai guna Aman digunakan Tidak bertentangan dengan peraturan perundang-undangan Tidak mengandung unsur promosi yang dilarang 5.3 Kondisi Barang Baru (brand new) Bukan barang bekas atau rekondisi Produk resmi pabrikan 5.4 Kualitas Kualitas baik dan layak pakai Spesifikasi sesuai yang ditetapkan dalam kontrak 6. Standar Mutu dan Keamanan Memenuhi standar mutu barang Aman untuk digunakan oleh penerima hadiah 7. Pengemasan dan Pengiriman Dikemas secara rapi dan aman Pengiriman hingga lokasi yang ditentukan oleh PPK 8. Jumlah Jumlah hadiah sesuai ketentuan dalam kontrak/SPK 9. Pemeriksaan dan Penggantian Pemeriksaan fisik dan kelengkapan Penggantian hadiah apabila terdapat kerusakan atau ketidaksesuaian spesifikasi 10. Garansi (Jika Barang Elektronik) Garansi resmi pabrikan minimal 1 (satu) tahun Layanan purna jual tersedia di Indonesia 11. Waktu Pelaksanaan Sesuai jadwal yang ditetapkan dalam kontrak/SPK 12. Serah Terima Pekerjaan Dilaksanakan setelah barang diterima dan dinyatakan sesuai Dibuktikan dengan Berita Acara Serah Terima (BAST)', 119872000, 'high', 'Penggunaan anggaran daerah untuk hadiah barang konsumtif seperti televisi, blender, dan kompor gas kepada wajib pajak berisiko tidak proporsional terhadap fungsi layanan perpajakan. Bentuk insentif ini lebih menyerupai pemberian hadiah daripada belanja yang langsung mendukung pelayanan publik, sehingga patut dinilai sebagai pengeluaran yang kurang tepat guna.', NULL, NULL, 3, 1, 1, 1, 1, 37874);
