INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61909820', 61909820, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'KELURAHAN RAMBUTAN - JAKTIM', 'Penyediaan  PJLP PPSU Kelurahan Rambutan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 5261841975, 'December 2025', 'APBD', 1, 1, '12 Bulan', 'Penyediaan Tenaga Penanganan Prasarana dan Sarana Umum pada Kelurahan Rambutan Tahun 2026 sesuai DPA sebanyak 75 orang, dengan rincian sebagai berikut: Jasa Tenaga Penanganan Prasarana dan Sarana Umum: 1. Penanganan prasarana dan sarana jalan 2. Penanganan prasarana dan sarana saluran 3. Penanganan prasarana dan sarana taman 4. Penanganan prasarana dan sarana kebersihan 5. Penanganan prasarana dan sarana penerangan jalan umum 6. Melaksanakan tugas lain yang diperintahkan oleh Pimpinan / Atasan Petugas Administrasi/Operator: 1. Membantu kegiatan pengadministrasian di Kantor Kelurahan Rambutan; 2. Membantu dan melaksanakan serta melayani kegiatan pelayanan masyarakat yang ada di Kantor Kelurahan Rambutan; 3. Membantu menyiapkan data yang dibutuhkan dalam kegiatan yang dilaksanakan di Kantor Kelurahan Rambutan; 4. Mengarsipkan semua dokumen yang berkaitan dengan tugas dan fungsi setiap pekerjaan yang ada di Kantor Kelurahan Rambutan; 5. Melaksanakan tugas lain yang diperintahkan oleh Pimpinan / Atasan Petugas Kebersihan Kantor: 1. Pembersihan ruangan (lantai, furniture, filing cabinet, almari, bufet, pembersihan pantry, tangga, dinding, kaca) 2. Pembersihan kamar mandi (Lantai kamar mandi, wastafel, kaca cermin, dinding (tembok/ kaca) kamar mandi, pintu kamar mandi, closet duduk, closet jongkrok, urinoir) 3. Membuang sampah ke tempat penampungan sampah 4. Mencuci tempat sampah 5. Membersihkan kaca luar dalam dan rangka alumunium/kayu 6. Membersihkan tembok / dinding 7. Membersihkan sawang pada plafond 8. Membersihkan pintu dan partisi kayu 9. Membersihkan bak mandi / ember 10. Membersihkan railing tangga 11. Membersihkan lobby, rabat / selasar bagian luar 12. Menyiapkan tissue gulung, hand soap dan kamper di kamar mandi 13. Melaksanakan tugas lain yang diperintahkan oleh Pimpinan / Atasan. Petugas Keamanan: 1. Melaksanakan penegakan peraturan dan ketentuan yang berlaku di Kantor Kelurahan Rambutan; 2. Memelihara, merawat, dan menjaga serta bertanggung jawab atas pengamanan benda/aset dan inventaris Kantor Kelurahan Rambutan; 3. Melaksanakan pengawasan rutin dan melakukan tindakan untuk memutuskan atau menyelesaikan perselisihan dan persoalan yang terjadi di lingkungan Kelurahan Rambutan; 4. Melaksanakan penjagaan dan pengawasan terhadap masuk dan keluarnya orang atau barang dan keadaan -keadaan atau hal-hal yang mencurigakan di area tempat tugasnya; 5. Melaksanakan pengamanan dan pengawalan terhadap pimpinan di Kelurahan Rambutan; 6. Melakukan tugas pengamanan di lingkungan kerja sesuai jadwal yang telah ditetapkan; 7. Mengambil langkah-langkah dan tindakan jika terjadi suatu tindak pidana di Lingkungan Kantor Kelurahan Rambutan; 8. Memberikan tanda bahaya atau keadaan darurat melalui alat-alat alarm dan kode atau isyarat tertentu jika terjadi kebakaran, bencana alam atau kejadian-kejadian yang dapat membahayakan jiwa; 9. Melaksanakan tugas lain yang diperintahkan oleh Pimpinan / Atasan. adapun jumlah Pengadaan Penyediaan Tenaga Penanganan Prasarana dan Sarana Umum pada Kelurahan Rambutan Tahun 2026 yang sedang menunggu persetujuan Sekretaris Daerah Provinsi DKI Jakarta sebanyak 3 Orang, setelah mendapatkan persetujuan akan dilakukan pengadaan/rekrutmen baru pada tahun 2026.', 'Petugas PPSU Tingkat Kelurahan (PJLP Kota Administrasi Jakarta Timur). Kualifikasi: Minimal SD Sederajat dan/atau dapat membaca menulis.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 39708);
