INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61905551', 61905551, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'BIRO PEMERINTAHAN', 'Belanja Jasa Konsultansi Berorientasi Layanan-Jasa Khusus Pelaksanaan Pengelolaan Pengaduan 20', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 90090000, 'December 2025', 'APBD', 1, 1, '1 orang x 12 bulan', 'Pelaksanaan verifikasi/pengecekan pengaduan dan/atau verifikasi tindak lanjut pengaduan oleh PD/UKPD/BUMD berdasarkan keyakinan yang wajar dan pengecekan lapangan terhadap pengaduan pada Aplikasi CRM', '1. Melakukan pengecekan berdasarkan keyakinan yang wajar pada Aplikasi CRM dan/atau pengecekan lapangan atas hasil tindak lanjut pengaduan yang telah dilakukan oleh PD/UKPD/BUMD pada Aplikasi CRM dengan memperhatikan foto, lokasi dan penjelasan hasil tindak lanjut pengaduan yang disesuaikan dengan substansi laporan pengaduan dan kriteria ketuntasan yang telah ditentukan dan/atau ketentuan yang berlaku; 2. Membuat pelaporan melalui kanal-kanal pengaduan resmi milik Pemerintah Provinsi DKI Jakarta apabila dalam pelaksanaan pengecekan lapangan ditemukan permasalahan lain yang perlu dilakukan penanganan dan tindak lanjut oleh Perangkat Daerah/Unit Kerja pada Perangkat Daerah terkait; 3. Melakukan penginputan Pengaduan yang bersifat lintas kewenangan antara PD/UKPD/BUMD pada satu ID Laporan yang bersumber pada Kanal JAKI ke dalam Aplikasi CRM; 4. Melakukan pengecekan terhadap laporan pengaduan pada fitur ticketing “Pindah Kelurahan” dan “Pindah SKPD” di Aplikasi CRM; 5. Membuat laporan rekapitulasi hasil pelaksanaan tugas; 6. Membuat rekapitulasi dan analisis terhadap laporan berulang pada Aplikasi CRM setiap minggu untuk dikoordinasikan dengan tim pada Kelompok Pengaduan; 7. Memetakan permasalahan dalam pelaksanaan tindak lanjut pengaduan masyarakat yang telah ditindaklanjuti oleh PD/UKPD/BUMD dan belum selesai pada Aplikasi CRM untuk dikoordinasikan dengan tim pada Kelompok Pengaduan. 8. Membuat paparan dalam bentuk dokumen atau presentasi sesuai dengan kebutuhan. 9. Membuat analisis dan rekomendasi terhadap upaya perbaikan dalam pengelolaan pengaduan masyarakat melalui Aplikasi CRM berdasarkan hasil pelaksanaan tugas setiap bulan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 39867);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61904269', 61904269, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK', 'Tenaga Teknis Pendukung Technician_2', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 85140000, 'December 2025', 'APBD', 1, 1, '1 Paket', 'Belanja Jasa Tenaga Teknis Pendukung Layanan Perangkat Sistem Elektronik Technician_2 (1 Orang x 12 Bulan)', '- Memberikan pelayanan teknis pada layanan Managed Service CCTV. - Melakukan pemantauan pada sistem monitoring layanan Managed Service CCTV, dan memberikan laporan jika ditemukan adanya gangguan atau keabnormalan. - Melakukan pengecekan perangkat hardware dan software di komputer/server sistem monitoring agar tetap dapat berjalan dengan optimal. - Melakukan kunjungan/survei ke lokasi site yang menjadi bagian dari kegiatan/pekerjaan Managed Service CCTV. - Membantu melakukan rekapitulasi, pemeriksaan data, dan pengolahan data hasil pekerjaan/layanan setiap bulan terhadap kegiatan/pekerjaan Managed Service CCTV. - Melakukan dokumentasi kegiatan/pekerjaan Managed Service CCTV. - Membuat dokumentasi dan laporan pekerjaan dalam bentuk hardcopy dan softcopy.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 39868);
